-- Beispieldaten für die Entwicklung.
--
-- Gleicher Inhalt wie scripts/seed.mjs, aber als reines SQL: so lässt es sich
-- ohne Node direkt im SQL-Editor von Supabase einfügen.
--
-- ACHTUNG: leert die betroffenen Tabellen vorher. Nicht auf einer
-- Datenbank mit echten Daten ausführen.
--
-- Erzeugt mit: node scripts/generate-seed-sql.mjs > supabase/seed.sql

begin;

delete from public.assignment;
delete from public.temp_assignment;
delete from public.temp_worker;
delete from public.leave_request;
delete from public.clothing_item;
delete from public.vehicle;
delete from public.project;
delete from public.employee;
delete from public.role;
delete from public.news;
delete from public.bridge_day;

update public.employee set mentor_id = '00000000-0000-4000-8000-000000000006' where id = '00000000-0000-4000-8000-000000000011';

commit;
